package org.weftkit.wiring.runtime.registry;

/**
 * The wiring data generated by the weftkit processor and consumed by {@link WeftLoader}. Unites
 * the stable {@link CoreRegistry} with one interface per layered feature: collaborators depend on
 * just their slice, one implementation provides the whole. All returned collections must be
 * immutable.
 */
public interface ComponentRegistry
        extends CoreRegistry, LazyRegistry, ProductRegistry, FlagRegistry, ModuleRegistry, AmbientRegistry {}
